import { Component, forwardRef, OnDestroy, OnInit } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { espdAbstractInputComponentInjectionToken, EspdAbstractSizeableInputDirective } from 'espd-common/forms/api';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { Subscription } from 'rxjs';

@Component({
	selector: 'espd-color-picker',
	templateUrl: './color-picker.component.html',
	imports: [
		ReactiveFormsModule,
		InputScaffoldComponent
	],
	styleUrls: ['./color-picker.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => ColorPickerComponent) }]
})
export class ColorPickerComponent extends EspdAbstractSizeableInputDirective implements OnInit, OnDestroy {

	private valueSubscription?: Subscription;

	ngOnInit(): void {
		super.ngOnInit();
		this.setControl();
	}

	public ngOnDestroy(): void {
		if (this.valueSubscription) {
			this.valueSubscription.unsubscribe();
		}
	}

	private setControl() {
		if (this.valueSubscription) {
			this.valueSubscription.unsubscribe();
		}
		if (this.control) {
			// because the formcontrol is bound to more than one input, re-set the value when one changes to update the rendered view of the other
			this.valueSubscription = this.control.valueChanges.subscribe(value => {
				this.control.setValue(value, { emitEvent: false });
			});
		}
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}